package ru.projectkingdom.npc;import java.util.*;import net.minecraft.server.*;import net.minecraft.server.level.*;import net.minecraft.core.*;public class KingdomCivicsData{private static final Map<MinecraftServer,KingdomCivicsData> ALL=new WeakHashMap<>();public static KingdomCivicsData get(MinecraftServer server){return ALL.computeIfAbsent(server,k->new KingdomCivicsData());}public Town town;public boolean foreign;public record Town(UUID id,UUID mayor){}public Town townById(UUID id){return town!=null&&town.id.equals(id)?town:null;}public Town townAt(ServerLevel level,BlockPos pos){return foreign?null:town;}public List<Town> towns(){return town==null?List.of():List.of(town);}}
